    throw new Error("advanceFen2: requires Zef to be 'pex'");
  }
  return { ...world, fen: "dor" };
}

/**
 * resetFen: Fen: pex -> nim.
 * This is intentionally limited to the pex state; a reset must not silently
 * alter Fen when it is still nim or has already advanced to dor.
 */
export function resetFen(world: WorldState): WorldState {
  if (world.fen !== "pex") {
    throw new Error("resetFen: Fen must be in state 'pex'");
  }
