//
// これは「文化的に継承されるartifact」ではなく、実験世界の固定された
// 外部境界条件である（schema.ts の WorldProtocol コメント参照）。
// H(G) は internal な rules.ts / entity module 構造を一切知らず、
// このファイルがexportする関数だけを呼ぶ。
//
// worker AIは、内部構造（vok/zef/tal/fen/osk ディレクトリ、rules.ts の分割方法等）を
// 自由にリファクタしてよいが、この protocol_adapter.ts が定義する
// エクスポート名・振る舞いだけは保持しなければならない
// （Generation 0で確定した固定契約）。

import { WorldProtocol, OperationResult } from "../../schema";
import { WorldState, createInitialWorld } from "./world";
import { advanceVok1, advanceVok2 } from "./vok/rules";
import { advanceZef1, advanceZef2 } from "./zef/rules";
import { advanceTal1 } from "./tal/rules";
import { advanceOsk1 } from "./osk/rules";
import { advanceFen1, advanceFen2, resetFen } from "./fen/rules";

function applyOperationToWorld(
  state: WorldState,
  operationDisplayName: string
): WorldState {
  switch (operationDisplayName) {
    case "advanceVok1":
      return advanceVok1(state);
    case "advanceVok2":
      return advanceVok2(state);
    case "advanceZef1":
      return advanceZef1(state);
    case "advanceZef2":
      return advanceZef2(state);
    case "advanceTal1":
      return advanceTal1(state);
    case "advanceOsk1":
      return advanceOsk1(state);
    case "advanceFen1":
      return advanceFen1(state);
    case "advanceFen2":
      return advanceFen2(state);
    case "resetFen":
      return resetFen(state);
    default:
      throw new Error(`Unknown operation: ${operationDisplayName}`);
  }
}

function asWorldState(state: unknown): WorldState {
  return state as WorldState;
}

/** The stable world protocol boundary. */
export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(
    state: unknown,
    operationDisplayName: string
  ): OperationResult {
    try {
      return {
        success: true,
        newState: applyOperationToWorld(
          asWorldState(state),
          operationDisplayName
        ),
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : String(error),
      };
    }
  },

  getEntityState(state: unknown, entityDisplayName: string): string {
    const world = asWorldState(state);
    switch (entityDisplayName) {
      case "Vok":
        return world.vok;
      case "Zef":
        return world.zef;
      case "Tal":
        return world.tal;
      case "Osk":
        return world.osk;
      case "Fen":
        return world.fen;
      default:
        throw new Error(`Unknown entity: ${entityDisplayName}`);
    }
  },

  toAbstractSnapshot(state: unknown): Record<string, string> {
    const world = asWorldState(state);
    return {
      Vok: world.vok,
      Zef: world.zef,
      Tal: world.tal,
      Osk: world.osk,
      Fen: world.fen,
    };
  },
};
